# Correspondances communes à tous les groupes — Ableton Live via AbletonOSC.
#
# TOUT passe par le canal 16 d'« Ableton Loopback », en CC uniquement.
# Vérifié le 2026-09-19 : sur ce canal, les CC sont ENTIÈREMENT libres (0 utilisé
# par le rig), et le set Funk n'a aucun mappage Cmd+M dessus. Les NOTES du canal 16
# sont prises par les déclencheurs FX et drums d'Evy — on n'y touche pas.
#
# Convention de plage :
#   20-29  transport et tempo        40-49  pistes
#   30-39  scènes                    50-59  routage (ClyphX)
#   100+   retour d'état, de Live vers le rig
#
# Le canal n'est PAS répété sur chaque ligne : il est posé une fois par « channel »
# dans le bloc des ports ci-dessous. Côté trevligaspel une commande s'écrit donc
# {cc:16,20,0} et un retour se lit
#   [(cc:16,100,*){@LivePlay:#@e_ccvalue#}]

group   common

# ┌── PORTS MIDI ─ inscrit par --ports le 2026-09-19 20:23 ──────────────────────
#   Le port actif est la ligne « port » non commentée ci-dessous.
#   Pour en changer : commenter celle-là, décommenter une autre.
#   Seuls les ports disponibles EN ENTRÉE ET EN SORTIE sont listés.
port    Ableton Loopback
# port    Daw2Mackie
# port    Daw2MackieB
# port    MPE loopback
# port    Mackie2Daw
# port    Mackie2XR18
# port    MackieB2Daw
# port    NetDevices
# port    Périphérique MIDI USB Port 1
# port    Périphérique MIDI USB Port 2
# port    RME Fireface UCX
# port    Réseau Session 1
# port    XR182Mackie
# port    rig-alert
#
#   Canal par défaut : les lignes send/verb/watch peuvent alors
#   omettre le canal (« send cc 20 /live/song/start_playing »).
channel 16
# └── fin des ports ────────────────────────────────────────────────────────
target  127.0.0.1:11000 -> 11001


# ══ COMMANDES  (le rig → Live) ══════════════════════════════════════════════

# ── transport ───────────────────────────────────────────────────────────────
send  cc 20   /live/song/start_playing          # STC : play_stop, start_playing
send  cc 21   /live/song/stop_playing
send  cc 22   /live/song/continue_playing
send  cc 23   /live/song/stop_all_clips
send  cc 24   /live/song/tap_tempo              # STC : tap_tempo

# Tempo : 0-127 → 50-177 bpm, la MÊME convention que le cc:7,20 déjà en place
# (@SongBpm-50). Le « .0 » force le float : Live refuse un tempo entier.
send  cc 25   $v+50   /live/song/set/tempo $a.0
send  cc 26   /live/song/set/metronome $a       # 0 ou 127 ; Live lit la valeur

# ── scènes  (413 des 560 messages que le rig envoyait à STC) ────────────────
send  cc 30   /live/view/set/selected_scene $a  # STC : select_scene, en absolu
send  cc 31   /live/scene/fire_selected         # STC : play_selected_scene
send  cc 32   /live/scene/fire $a               # lancer une scène par son index

# ── pistes  (l'index de piste EST la valeur du CC) ──────────────────────────
send  cc 40   /live/view/set/selected_track $a
send  cc 41   /live/track/set/arm  $a true      # STC : arm
send  cc 42   /live/track/set/arm  $a false
send  cc 43   /live/track/set/solo $a true      # STC : solo
send  cc 44   /live/track/set/solo $a false
send  cc 45   /live/track/set/mute $a true      # STC : mute
send  cc 46   /live/track/set/mute $a false
send  cc 47   /live/track/set/current_monitoring_state $a 0   # STC : switch_monitoring (In)
send  cc 48   /live/track/set/current_monitoring_state $a 1   #                          (Auto)
send  cc 49   /live/track/set/current_monitoring_state $a 2   #                          (Off)

# Les variantes EXCLUSIVES de STC (solo_exclusive, mute_exclusive, solo_kill) n'ont
# pas d'équivalent en une adresse : ce sont des boucles sur toutes les pistes. Elles
# s'écrivent côté trevligaspel, qui connaît le nombre de pistes par le CC 105.


# ══ CLYPHX  (les deux macros qui restaient) ═════════════════════════════════
#
# $G_FNK$ route Main et C-Cue vers Ext. Out 1/2. AbletonOSC l'expose, mais l'index
# du routage dépend de l'interface audio de LA machine : il faut le lire une fois,
# puis écrire les deux lignes ci-dessous avec les bons numéros.
#
#   oscsend /live/track/get/available_output_routing_types 0
#
# send  cc 16 50   /live/track/set/output_routing_type    0 <index Ext. Out>
# send  cc 16 51   /live/track/set/output_routing_channel 0 <index 1/2>


# ══ RETOUR D'ÉTAT  (Live → le rig) ══════════════════════════════════════════
#
# C'est la seule chose que le MIDI seul ne pouvait pas donner, et la raison d'être
# de la passerelle : le rig cesse d'envoyer en aveugle.

watch /live/song/get/is_playing         0  ->  cc 100
watch /live/view/get/selected_scene     0  ->  cc 101   # borné à 127, la passerelle le dit
watch /live/song/get/tempo              0  ->  cc 102  $v-50
watch /live/view/get/selected_track     0  ->  cc 103
watch /live/song/get/num_scenes         0  ->  cc 104
watch /live/song/get/num_tracks         0  ->  cc 105
watch /live/song/get/metronome          0  ->  cc 106

# ── ce que le MIDI ne peut pas porter : les textes ──────────────────────────
# Ils vont dans le fichier d'état JSON, relu par le JS du Stream Deck avec
# io.loadFile — exactement le motif de songs/loader.js.
text  /live/song/get/track_names   ->  tracks
text  /live/song/get/scenes/name   ->  scenes


# ══ GESTES  (calculés sur l'état, pas une simple adresse) ═══════════════════
verb  cc 60   scene.prev
verb  cc 61   scene.next
verb  cc 62   scene.first
verb  cc 63   scene.last
verb  cc 64   scene.play_next
verb  cc 65   scene.play_prev
verb  cc 66   scene.scroll          # CC relatif : 1-63 monte, 65-127 descend
verb  cc 70   track.prev
verb  cc 71   track.next
verb  cc 72   track.scroll
verb  cc 80   transport.toggle      # STC : play_stop
verb  cc 81   transport.pause
verb  cc 82   tempo.up
verb  cc 83   tempo.down
verb  cc 84   tempo.nudge           # relatif
verb  cc 90   arm.exclusive
verb  cc 91   solo.exclusive
verb  cc 92   mute.exclusive
verb  cc 93   arm.kill
verb  cc 94   solo.kill
verb  cc 95   mute.kill


# ══ CE QUE LA PASSERELLE PEUT REPRENDRE AUX AUTRES SCRIPTS ══════════════════
#
# ActionStation publie aujourd'hui l'état des pistes vers son plugin Stream Deck
# (noms, couleurs, mute/solo/arm, VU). AbletonOSC expose tout cela : il suffit de
# décommenter. Les VU sont DÉBITÉS — c'est ce qui a saturé le CPU du plugin MIDI
# le 13/09, et 120 ms avait réglé l'affaire.
#
# watch /live/track/get/output_meter_level 0  ->  cc 110  every 120ms
# watch /live/track/get/color              0  ->  cc 111
# text  /live/song/get/track_names             ->  tracks     (déjà actif plus haut)
#
# Ce qu'AbletonOSC ne sait PAS faire, et qui justifie de garder un script à part :
#   le NAVIGATEUR de Live — charger un instrument ou un plugin depuis le deck.
#   C'est la seule fonction d'ActionStation et de HJF_Plugins qui n'a pas
#   d'équivalent OSC dans la version officielle.
